-- ============================================================
-- InfoWebWorld — Professional Services 100-listing seed batch
--
-- 100 real Professional Services firms, every renderable section
-- populated (services/key features, industries, use cases, company
-- sizes, pros, cons, support, training, FAQs, header tags, pricing
-- model, languages). Pricing tiers / starting price / integrations /
-- compliance / awards are left NULL (not published / not applicable
-- for these firms) and render as empty-state, same as the AI/ML seed.
--
-- Logo = Google favicon API. Screenshots come from
-- scripts/capture-screenshots.mjs after this SQL is loaded.
-- All rows: status='active', payment_status='completed', user_id=NULL
-- (live + claimable). Re-runnable: deletes its own slugs first.
-- Run in phpMyAdmin → SQL tab.
-- ============================================================

SET @free_plan := (SELECT id FROM plans WHERE is_active = 1 ORDER BY price ASC LIMIT 1);
SET @fallback_country := (SELECT id FROM countries WHERE code = 'US' LIMIT 1);

DELETE FROM submissions WHERE slug IN (
  'deloitte', 'pwc', 'ey', 'kpmg', 'rsm-us', 'grant-thornton',
  'bdo-usa', 'crowe', 'baker-tilly', 'moss-adams', 'cohnreznick', 'bench',
  'pilot', 'mckinsey-company', 'boston-consulting-group', 'bain-company', 'accenture', 'oliver-wyman',
  'kearney', 'l-e-k-consulting', 'west-monroe', 'simon-kucher', 'zs-associates', 'fti-consulting',
  'alixpartners', 'alvarez-marsal', 'fisher-investments', 'edward-jones', 'charles-schwab', 'fidelity-investments',
  'vanguard', 'mercer', 'wealthfront', 'betterment', 'empower', 'robert-half',
  'randstad', 'adecco', 'manpowergroup', 'hays', 'michael-page', 'korn-ferry',
  'heidrick-struggles', 'spencer-stuart', 'egon-zehnder', 'russell-reynolds', 'ogilvy', 'wpp',
  'publicis-groupe', 'omnicom-group', 'dentsu', 'bbdo', 'edelman', 'weber-shandwick',
  'interbrand', 'landor', 'nielsen', 'ipsos', 'kantar', 'latham-watkins',
  'kirkland-ellis', 'skadden', 'paul-weiss', 'davis-polk', 'cravath', 'sullivan-cromwell',
  'cooley', 'wilson-sonsini', 'dla-piper', 'baker-mckenzie', 'jones-day', 'morgan-lewis',
  'fragomen', 'fish-richardson', 'cbre', 'jll', 'cushman-wakefield', 'colliers',
  'newmark', 'savills', 'marsh', 'aon', 'wtw', 'arthur-j-gallagher',
  'lockton', 'hub-international', 'embroker', 'goldman-sachs', 'morgan-stanley', 'lazard',
  'evercore', 'moelis-company', 'houlihan-lokey', 'jefferies', 'rothschild-co', 'gensler',
  'aecom', 'jacobs', 'perkins-will', 'arup'
);

-- 1/100  Deloitte
INSERT INTO submissions (
  uuid, company_name, slug, contact_name, email, phone_code, website,
  category_id, country_id, city, hq_location,
  tagline, description, logo_url, founded_year, team_size,
  linkedin, listing_mode, pricing_model,
  key_features, features, header_tags, pros, cons,
  industries_served, use_cases, target_company_sizes,
  support_channels, training_options, languages, faqs,
  has_free_trial, has_free_version, has_ios_app, has_android_app,
  status, payment_status, plan_id,
  activated_at, approved_at, created_at, updated_at
)
SELECT
  UUID(), 'Deloitte', 'deloitte', 'Deloitte Team', 'info@deloitte.com', '+44', 'https://www.deloitte.com',
  (SELECT id FROM categories WHERE slug = 'audit-assurance' LIMIT 1),
  COALESCE((SELECT id FROM countries WHERE code = 'GB' LIMIT 1), @fallback_country),
  'London', 'London, GB',
  'The world''s largest professional services firm — audit, consulting, tax, and advisory',
  'Deloitte is the largest of the Big Four professional services networks, delivering audit & assurance, consulting, tax, risk, and financial advisory to a majority of the world''s largest companies across 150+ countries.',
  'https://www.google.com/s2/favicons?domain=deloitte.com&sz=256', 1845, '1000+',
  'https://www.linkedin.com/company/deloitte', 'product', 'Custom quote',
  '[{"name": "Audit & Assurance", "description": "Independent financial statement audits, internal controls, and assurance over financial reporting."}, {"name": "Tax", "description": "Corporate, international, indirect, and personal tax planning, compliance, and advisory."}, {"name": "Advisory", "description": "Transaction, risk, and management advisory across the business lifecycle."}, {"name": "Accounting & Bookkeeping", "description": "Day-to-day accounting, financial close, and managed bookkeeping services."}, {"name": "Outsourced Finance", "description": "Outsourced controller and CFO services for growing organizations."}]',
  '["Financial statement audits", "Corporate tax", "International tax", "Bookkeeping", "Payroll", "Risk advisory", "Transaction services", "Forensic accounting"]',
  '["Accounting", "Tax", "Advisory"]',
  '["Deep regulatory and industry expertise", "Established reputation and credentials", "Broad service coverage under one roof", "Global delivery capability"]',
  '["Pricing is engagement-based, not transparent upfront", "Best suited to mid-market and enterprise budgets"]',
  '["Financial services", "Technology", "Healthcare", "Manufacturing", "Real estate", "Nonprofit", "Retail & consumer", "Public sector"]',
  '["Annual financial statement audit", "Corporate tax return preparation", "Outsourced bookkeeping & close", "M&A financial due diligence", "Internal controls & SOX readiness"]',
  '["Small businesses", "Midsize", "Enterprises"]',
  '["Dedicated engagement team", "Email", "Phone", "Client portal"]',
  '["Webinars", "Industry insights & guides", "Client onboarding"]',
  '["English"]',
  '[{"question": "What services does Deloitte offer?", "answer": "Deloitte provides audit & assurance, tax, advisory, and related professional services. Browse the service list and full profile above for details."}, {"question": "How much does Deloitte cost?", "answer": "Deloitte prices engagements on a custom-quote basis — fees depend on scope, complexity, and the services you need. Contact the firm through its profile for a tailored quote."}, {"question": "Who does Deloitte work with?", "answer": "Deloitte serves clients ranging from small businesses to enterprises across industries such as financial services, technology, healthcare."}, {"question": "How do I get started with Deloitte?", "answer": "Reach out via Deloitte''s website or this InfoWebWorld profile to scope your needs and request a proposal; a dedicated team is typically assigned to your engagement."}]',
  0, 0, 0, 0,
  'active', 'completed', @free_plan,
  NOW(), NOW(), NOW(), NOW();

